#include <stdio.h>
#define MAX 100

int main(void) {
    int a[MAX], n, i, key, pos, max, min, t;
    long sum = 0;

    printf("Enter N (1-%d): ", MAX);
    if (scanf("%d", &n) != 1 || n < 1 || n > MAX) {
        printf("Invalid N\n");
        return 1;
    }
    printf("Enter %d integers: ", n);
    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;

    /* 1. Display all elements */
    printf("Elements:");
    for (i = 0; i < n; i++)
        printf(" %d", a[i]);
    printf("\n");

    /* 2. Maximum and minimum */
    max = min = a[0];
    for (i = 1; i < n; i++) {
        if (a[i] > max) max = a[i];
        if (a[i] < min) min = a[i];
    }
    printf("Maximum = %d, Minimum = %d\n", max, min);

    /* 3. Sum and average */
    for (i = 0; i < n; i++)
        sum += a[i];
    printf("Sum = %ld, Average = %.2f\n", sum, (double)sum / n);

    /* 4. Linear search */
    printf("Enter element to search: ");
    if (scanf("%d", &key) != 1)
        return 1;
    pos = -1;
    for (i = 0; i < n; i++) {
        if (a[i] == key) {
            pos = i;
            break;
        }
    }
    if (pos >= 0)
        printf("%d found at position %d\n", key, pos + 1);
    else
        printf("%d not found\n", key);

    /* 5. Reverse in place: swap a[i] with a[n-1-i] */
    for (i = 0; i < n / 2; i++) {
        t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
    printf("Reversed:");
    for (i = 0; i < n; i++)
        printf(" %d", a[i]);
    printf("\n");
    return 0;
}

