    int i, j, k;
    for (i = 1; i < n; i++)
        for (j = 0; j < i; j++)
            for (k = 0; k < i; k++)
                x = x + 1;
    return x;
}

/* recursive version: f(n) = f(n-1) + (n-1)^2, f(1) = 0 */
long f(int n) {
    if (n <= 1)
        return 0;
    return f(n - 1) + (long)(n - 1) * (n - 1);
}

int main(void) {
    int n;
    for (n = 1; n <= 6; n++)
        printf("n=%d loops=%ld recursive=%ld\n", n, loops(n), f(n));
    return 0;
}

Output (loop and recursive versions agree):
n=1 loops=0 recursive=0
n=2 loops=1 recursive=1
n=3 loops=5 recursive=5
n=4 loops=14 recursive=14
n=5 loops=30 recursive=30
n=6 loops=55 recursive=55

Check with the formula for n = 6: 5 × 6 × 11 / 6 = 55. The loops take O(n³) steps; the recursion takes O(n) calls (and the closed formula O(1)).

