        for (j = 0; j < i; j++)
            for (k = 0; k < i; k++)
                x = x + 1;
    return x;
}

/* recursive version: f(n) = f(n-1) + (n-1)^2, f(1) = 0 */
long f(int n) {
    if (n <= 1)
        return 0;
    return f(n - 1) + (long)(n - 1) * (n - 1);
}

int main(void) {
